<?php
require_once __DIR__ . '/../includes/bootstrap.php';
require_role('System Administrator','Scholarship Coordinator');
$pageTitle='Scholarship Monitoring';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  if(!verify_csrf_token($_POST['csrf_token']??null))throw new RuntimeException('Invalid request. Refresh the page.');
  $appId=filter_var($_POST['scholarship_application_id']??null,FILTER_VALIDATE_INT);$performance=trim($_POST['academic_performance']??'');$behavior=trim($_POST['behavior_remarks']??'');$participation=$_POST['participation_status']??'';$eligibility=$_POST['renewal_eligibility']??'';$date=$_POST['monitoring_date']??date('Y-m-d');
  if(!$appId||!in_array($participation,['Qualified','Currently Enrolled','Removed'],true)||!in_array($eligibility,['Eligible','Not Eligible','Pending'],true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Complete the monitoring fields with valid values.');
  $check=$pdo->prepare("SELECT scholarship_application_id FROM scholarship_applications WHERE scholarship_application_id=:id AND application_status='Approved'");$check->execute(['id'=>$appId]);if(!$check->fetch())throw new RuntimeException('Select an approved scholarship application.');
  $q=$pdo->prepare('INSERT INTO scholarship_monitoring(scholarship_application_id,academic_performance,behavior_remarks,participation_status,renewal_eligibility,monitoring_date) VALUES(:app,:performance,:behavior,:participation,:eligibility,:date)');
  $q->execute(['app'=>$appId,'performance'=>$performance?:null,'behavior'=>$behavior?:null,'participation'=>$participation,'eligibility'=>$eligibility,'date'=>$date]);$success='Scholarship monitoring record saved.';
 }catch(PDOException $ex){error_log('Scholarship monitoring: '.$ex->getMessage());$error='Unable to save the monitoring record.';}catch(RuntimeException $ex){$error=$ex->getMessage();}
}
$approved=$pdo->query("SELECT sa.scholarship_application_id,st.first_name,st.last_name,sp.program_name,y.school_year FROM scholarship_applications sa JOIN students st ON st.student_id=sa.student_id JOIN special_programs sp ON sp.program_id=sa.program_id JOIN school_years y ON y.school_year_id=sa.school_year_id WHERE sa.application_status='Approved' ORDER BY st.last_name,st.first_name")->fetchAll();
$records=$pdo->query("SELECT sm.*,st.first_name,st.last_name,sp.program_name FROM scholarship_monitoring sm JOIN scholarship_applications sa ON sa.scholarship_application_id=sm.scholarship_application_id JOIN students st ON st.student_id=sa.student_id JOIN special_programs sp ON sp.program_id=sa.program_id ORDER BY sm.monitoring_date DESC,sm.monitoring_id DESC")->fetchAll();
require_once __DIR__.'/../includes/header.php';
?>
<section class="form-card form-card-wide"><h1>Scholarship Monitoring</h1><p class="muted">Record academic performance, behavior, participation, and renewal eligibility for approved scholars.</p><?php if($success):?><p class="success-message"><?=e($success)?></p><?php endif;?><?php if($error):?><p class="error-message"><?=e($error)?></p><?php endif;?>
<h2>New Monitoring Record</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><label>Approved scholar<select name="scholarship_application_id" required><option value="">Select student/program</option><?php foreach($approved as $a):?><option value="<?=(int)$a['scholarship_application_id']?>"><?=e($a['last_name'].', '.$a['first_name'].' — '.$a['program_name'].' ('.$a['school_year'].')')?></option><?php endforeach;?></select></label><label>Academic performance<textarea name="academic_performance" rows="3"></textarea></label><label>Behavior remarks<textarea name="behavior_remarks" rows="3"></textarea></label><label>Participation status<select name="participation_status"><option>Qualified</option><option>Currently Enrolled</option><option>Removed</option></select></label><label>Renewal eligibility<select name="renewal_eligibility"><option>Pending</option><option>Eligible</option><option>Not Eligible</option></select></label><label>Monitoring date<input type="date" name="monitoring_date" value="<?=e(date('Y-m-d'))?>" required></label><button class="button button-primary">Save Monitoring</button></form>
<h2>Monitoring History</h2><div class="table-responsive"><table><thead><tr><th>Date</th><th>Student</th><th>Program</th><th>Participation</th><th>Renewal</th><th>Academic / Behavior Notes</th></tr></thead><tbody><?php foreach($records as $r):?><tr><td><?=e($r['monitoring_date'])?></td><td><?=e($r['first_name'].' '.$r['last_name'])?></td><td><?=e($r['program_name'])?></td><td><?=e($r['participation_status'])?></td><td><?=e($r['renewal_eligibility'])?></td><td><?=e(trim(($r['academic_performance']??'').' '.($r['behavior_remarks']??'')))?></td></tr><?php endforeach;?><?php if(!$records):?><tr><td colspan="6">No monitoring records yet.</td></tr><?php endif;?></tbody></table></div></section>
<?php require_once __DIR__.'/../includes/footer.php';?>
